package popcount

import "math/bits"

// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	n := 0
	const (
		m1 = 0x5555555555555555
		m2 = 0x3333333333333333
		m4 = 0x0f0f0f0f0f0f0f0f
		m8 = 0x00ff00ff00ff00ff
		h  = 0x0001000100010001
	)
	for len(xs) >= 8 {
		// Per word: nibble counts (<=4); pairs share the nibble->byte step.
		x := xs[0]
		x -= (x >> 1) & m1
		x = (x & m2) + ((x >> 2) & m2)
		y := xs[1]
		y -= (y >> 1) & m1
		y = (y & m2) + ((y >> 2) & m2)
		x += y
		a := (x + (x >> 4)) & m4

		x = xs[2]
		x -= (x >> 1) & m1
		x = (x & m2) + ((x >> 2) & m2)
		y = xs[3]
		y -= (y >> 1) & m1
		y = (y & m2) + ((y >> 2) & m2)
		x += y
		a += (x + (x >> 4)) & m4

		x = xs[4]
		x -= (x >> 1) & m1
		x = (x & m2) + ((x >> 2) & m2)
		y = xs[5]
		y -= (y >> 1) & m1
		y = (y & m2) + ((y >> 2) & m2)
		x += y
		a += (x + (x >> 4)) & m4

		x = xs[6]
		x -= (x >> 1) & m1
		x = (x & m2) + ((x >> 2) & m2)
		y = xs[7]
		y -= (y >> 1) & m1
		y = (y & m2) + ((y >> 2) & m2)
		x += y
		a += (x + (x >> 4)) & m4

		// Bytes <= 64 here; fold to 16-bit lanes and sum with a multiply.
		a = (a & m8) + ((a >> 8) & m8)
		n += int((a * h) >> 48)
		xs = xs[8:]
	}
	// At most 7 words remain; index directly, with no reslicing.
	if l := len(xs); l >= 4 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3])
		if l >= 6 {
			n += bits.OnesCount64(xs[4]) + bits.OnesCount64(xs[5])
			if l == 7 {
				n += bits.OnesCount64(xs[6])
			}
		} else if l == 5 {
			n += bits.OnesCount64(xs[4])
		}
	} else if l >= 2 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1])
		if l == 3 {
			n += bits.OnesCount64(xs[2])
		}
	} else if l == 1 {
		n += bits.OnesCount64(xs[0])
	}
	return n
}

